func (q *Queries) ListWorkflowRoleResolutions(ctx context.Context, workflowRunID pgtype.UUID) ([]MulticaWorkflowRoleResolution, error) {
	rows, err := q.db.Query(ctx, listWorkflowRoleResolutions, workflowRunID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MulticaWorkflowRoleResolution{}
	for rows.Next() {
		var i MulticaWorkflowRoleResolution
		if err := rows.Scan(
			&i.ID,
			&i.WorkflowRunID,
			&i.WorkflowNodeRunID,
			&i.SlotType,
			&i.RoleID,
			&i.RoleNameSnapshot,
			&i.RoleDescriptionSnapshot,
			&i.Status,
			&i.ResolvedUserID,
			&i.Source,
			&i.ReasonCode,
			&i.ReasonDetail,
			&i.Version,
			&i.ResolvedBy,
			&i.ResolvedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

